#!/usr/bin/env node
/**
 * ULS Override File Generator
 * 
 * Creates override files for ULS components with helpful templates.
 * Inspired by Semantic UI's approach but adapted for ULS architecture.
 * 
 * Usage:
 *   Interactive mode: npx uls-override
 *   CLI mode: npx uls-override button --type=element --out=src/styles/uls/overrides
 */

const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');
const readline = require('readline');

// Component type mappings
const TYPE_DIRS = {
  base: 'base',
  element: 'elements',
  collection: 'collections',
  module: 'modules',
  theme: 'themes'
};

const ENTRY_FILE_NAME = 'uls-overrides.less';
const ENTRY_SECTION_MARKERS = {
  base: '// ::ULS-AUTO-BASE::',
  element: '// ::ULS-AUTO-ELEMENTS::',
  collection: '// ::ULS-AUTO-COLLECTIONS::',
  module: '// ::ULS-AUTO-MODULES::',
  theme: '// ::ULS-AUTO-THEMES::'
};

const CONFIG_FILE_NAMES = [
  'uls.config.cjs',
  'uls.config.js',
  'uls.override.config.cjs',
  'uls.override.config.js',
];

// Detect if running from ULS repo or user's project
function isULSRepo() {
  const packageJsonPath = path.resolve(__dirname, '../package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      return pkg.name === 'uls-v2';
    } catch (e) {
      return false;
    }
  }
  return false;
}

// Find user's project root (where package.json exists)
function findProjectRoot() {
  let currentDir = process.cwd();
  const root = path.parse(currentDir).root;
  
  while (currentDir !== root) {
    const packageJsonPath = path.join(currentDir, 'package.json');
    if (fs.existsSync(packageJsonPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
        // If it's not ULS repo, it's user's project
        if (pkg.name !== 'uls-v2') {
          return currentDir;
        }
      } catch (e) {
        // Continue searching
      }
    }
    currentDir = path.dirname(currentDir);
  }
  
  // Fallback to current working directory
  return process.cwd();
}

const DEFAULT_APP_NAME = 'default';

function resolveAppName(config = {}) {
  const fromEnv = process.env.ULS_APP;
  const fromConfig = config.defaultApp;
  const resolved = (fromEnv || fromConfig || DEFAULT_APP_NAME).toString().trim();
  return resolved || DEFAULT_APP_NAME;
}

// Get override directory based on context (per-app)
function getOverridesDir({ outputDir, config }) {
  if (outputDir) {
    return path.resolve(process.cwd(), outputDir);
  }

  if (config) {
    if (config.overridesDir) {
      return path.resolve(process.cwd(), config.overridesDir);
    }
    if (config.outputDir) {
      return path.resolve(process.cwd(), config.outputDir);
    }
    if (config.stylesPath) {
      const appName = resolveAppName(config);
      return path.resolve(process.cwd(), path.join(config.stylesPath, appName, 'overrides'));
    }
  }

  if (isULSRepo()) {
    return path.resolve(__dirname, '../src/styles/uls-overrides/less/uls-primereact');
  }

  const projectRoot = findProjectRoot();
  return path.resolve(projectRoot, 'src/styles/uls', DEFAULT_APP_NAME, 'overrides');
}

function getAppRootDir({ overridesDir, config }) {
  // If config specifies stylesPath, use it (preferred)
  if (config && config.stylesPath) {
    const appName = resolveAppName(config);
    return path.resolve(process.cwd(), config.stylesPath, appName);
  }

  // Fallback: assume overridesDir is "<appRoot>/overrides"
  return path.resolve(overridesDir, '..');
}

// Main execution
(async function() {
  try {
    // Get command line arguments
    const args = process.argv.slice(2);
    const options = parseArgs(args);

    // Handle config initialization flag
    const initConfigFlag = options['init-config'] || options.initConfig || options.initconfig;
    if (initConfigFlag) {
      await initConfig(options);
      process.exit(0);
    }

    const config = await loadConfig();
    
    let componentName = options.component || args[0];
    let componentType = options.type || config.type;
    let template = options.template || config.template || 'basic';
    let outputDir = options.out || options.output || config.outputDir;
    
    // Interactive mode if no component name provided
    if (!componentName) {
      const defaults = detectDefaultPaths();
      const inquirer = await getInquirer();
      let answers;

      if (inquirer) {
        answers = await inquirer.prompt([
          {
            type: 'input',
            name: 'componentName',
            message: 'Component name:',
            validate: (input) => input.trim().length > 0 || 'Component name is required'
          },
          {
            type: 'list',
            name: 'type',
            message: 'Component type:',
            choices: [
              { name: 'Element (buttons, inputs, etc.)', value: 'element' },
              { name: 'Collection (cards, accordions, etc.)', value: 'collection' },
              { name: 'Module (dialogs, tooltips, etc.)', value: 'module' },
              { name: 'Base (root config, variables)', value: 'base' },
              { name: 'Theme (theme-specific)', value: 'theme' }
            ],
            default: componentType || config.type || 'element'
          },
          {
            type: 'input',
            name: 'outputDir',
            message: 'Output directory:',
            default: outputDir
              || config.outputDir
              || defaults.outputDir,
            validate: (input) => input.trim().length > 0 || 'Output directory is required'
          }
        ]);
      } else {
        answers = await promptUsingReadline({
          defaults,
          componentType: componentType || config.type || 'element',
          outputDir: outputDir || config.outputDir || defaults.outputDir
        });
      }
      
      componentName = answers.componentName.trim();
      componentType = answers.type;
      outputDir = answers.outputDir.trim();
    }
    
    // Set defaults
    componentType = componentType || 'element';
    
    // Determine target directory
    const overridesBaseDir = getOverridesDir({ outputDir, config });
    const appRootDir = getAppRootDir({ overridesDir: overridesBaseDir, config });
    const targetDir = path.join(overridesBaseDir, TYPE_DIRS[componentType] || 'elements');
    const targetFile = path.join(targetDir, `${componentName}.overrides.less`);
    
    // Ensure directory exists
    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }
    
    // Check if file already exists
    if (fs.existsSync(targetFile)) {
      console.log(`\n⚠️  Warning: ${path.relative(process.cwd(), targetFile)} already exists`);
      console.log('   Delete it first or use a different name.\n');
      process.exit(1);
    }
    
    // Generate override file content
    const content = generateOverrideContent(componentName, componentType, template);
    
    // Write file
    fs.writeFileSync(targetFile, content, 'utf8');
    
    const entryFilePath = ensureEntryFile(overridesBaseDir);
    registerOverrideImport(entryFilePath, componentType, componentName);

    console.log(`\n✅ Created override file: ${path.relative(process.cwd(), targetFile)}`);
    console.log(`\n📝 Next steps:`);
    console.log(`   1. Edit the file to customize your overrides`);
    console.log(`   2. Import entry updated: ${path.relative(process.cwd(), entryFilePath)}`);
    
    if (!isULSRepo()) {
      console.log(`   3. Import in your main.less:`);
      console.log(`      @import "./src/styles/uls/<appName>/uls-master";`);
    } else {
      console.log(`   3. Import in your main.less: @import 'uls-styles/uls'; @import "uls-overrides/less/uls-primereact/uls-overrides";`);
    }
    console.log('');
    
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    process.exit(1);
  }
})();

// ============================================================================
// Helper Functions
// ============================================================================

async function getInquirer() {
  if (getInquirer.cache) {
    return getInquirer.cache;
  }

  try {
    // Try CommonJS require first (works inside ULS repo)
    // eslint-disable-next-line global-require
    const mod = require('inquirer');
    getInquirer.cache = mod;
    return mod;
  } catch (requireErr) {
    try {
      const mod = await import('inquirer');
      getInquirer.cache = mod.default || mod;
      return getInquirer.cache;
    } catch (importErr) {
      console.warn('\n⚠️  Warning: inquirer package not found. Falling back to basic prompts.');
      return null;
    }
  }
}

function parseArgs(args) {
  const options = {};
  args.forEach(arg => {
    if (arg.startsWith('--')) {
      const [key, value] = arg.substring(2).split('=');
      options[key] = value || true;
    } else if (!arg.startsWith('-') && !options.component) {
      // First non-flag argument is component name
      options.component = arg;
    }
  });
  return options;
}

async function initConfig(options) {
  const cwd = process.cwd();
  const defaultFileName = 'uls.config.cjs';
  const fileName = options['config-name'] || options.configname || defaultFileName;
  const targetPath = path.join(cwd, fileName);

  if (fs.existsSync(targetPath)) {
    console.log(`\n⚠️  Config file already exists: ${path.relative(process.cwd(), targetPath)}`);
    console.log('   Delete it first or choose a different name with --config-name\n');
    return;
  }

  const defaults = detectDefaultPaths();

  let outputDir = options.out || options.output;
  let type = options.type || 'element';
  let template = options.template || 'basic';

  // Default configuration values (no prompts needed)
  outputDir = outputDir || defaults.outputDir;
  type = type || 'element';
  template = template || 'basic';

  const contents = `/**
 * ULS Override Generator Config
 * Generated via: npx uls-override --init-config
 */
module.exports = {
  // Where override files should be created
  outputDir: '${outputDir}',

  // Default component type (element | collection | module | base | theme)
  type: '${type}',

  // Default template style (basic | full | minimal)
  template: '${template}',
};
`;

  fs.writeFileSync(targetPath, contents, 'utf8');
  console.log(`\n✅ Created config file: ${path.relative(process.cwd(), targetPath)}\n`);
}

async function loadConfig() {
  const cwd = process.cwd();
  const defaults = detectDefaultPaths();

  for (const filename of CONFIG_FILE_NAMES) {
    const filePath = path.join(cwd, filename);
    if (!fs.existsSync(filePath)) {
      continue;
    }

    try {
      const config = await importConfigFile(filePath);
      if (config && typeof config === 'object') {
        return config;
      }
    } catch (err) {
      console.warn(`\n⚠️  Ignoring config file ${filename}: ${err.message}`);
    }
  }

  return {
    outputDir: defaults.outputDir,
  };
}

async function importConfigFile(filePath) {
  try {
    delete require.cache[require.resolve(filePath)];
    return require(filePath);
  } catch (err) {
    if (err.code === 'ERR_REQUIRE_ESM') {
      const module = await import(pathToFileURL(filePath));
      return module.default || module;
    }
    throw err;
  }
}

function generateOverrideContent(name, type, templateStyle) {
  const className = type === 'base' ? getBaseClassName(name) : `uls-${name}`;
  const date = new Date().toISOString().split('T')[0];
  
  let content = '';
  
  // Header
  content += `// ==========================================================================\n`;
  content += `// ULS PrimeReact - ${capitalize(name)} Component Overrides\n`;
  content += `// ==========================================================================\n`;
  content += `// Customize ${name} component styles here.\n`;
  content += `// This file is automatically imported via uls-overrides.less\n`;
  content += `//\n`;
  content += `// Created: ${date}\n`;
  content += `// ==========================================================================\n\n`;
  
  // Template-specific content
  if (templateStyle === 'full') {
    content += generateFullTemplate(className, name, type);
  } else if (templateStyle === 'minimal') {
    content += generateMinimalTemplate(className);
  } else {
    content += generateBasicTemplate(className, name, type);
  }
  
  return content;
}

function detectDefaultPaths() {
  const cwd = process.cwd();
  const candidates = [
    'src/styles/uls/default/overrides',
    'src/styles/uls/default/overrides',
    'src/styles/uls-overrides/less/uls-primereact',
    'src/styles/uls-overrides/less/uls-primereact',
    'src/styles/uls-overrides',
    'src/styles/uls-overrides',
  ];

  const outputDir = candidates.find((relativePath) =>
    fs.existsSync(path.join(cwd, relativePath))
  ) || candidates[0];

  return { outputDir };
}

function generateBasicTemplate(className, name, type) {
  let template = '';
  
  if (type === 'base') {
    template += `// ==========================================================================\n`;
    template += `// ${capitalize(name)} OVERRIDES\n`;
    template += `// ==========================================================================\n\n`;
    template += `// Example: Override CSS custom properties\n`;
    template += `:root {\n`;
    template += `  // --uls-${name.replace(/-/g, '-')}: your-value;\n`;
    template += `}\n\n`;
    template += `// Example: Override LESS variables\n`;
    template += `// @${name.replace(/-/g, '-')}-variable: your-value;\n`;
  } else {
    template += `// ==========================================================================\n`;
    template += `// ${capitalize(name)} COMPONENT OVERRIDES\n`;
    template += `// ==========================================================================\n\n`;
    template += `.${className} {\n`;
    template += `  // Add your custom styles here\n`;
    template += `  // Example:\n`;
    template += `  // border-radius: @border-radius-lg;\n`;
    template += `  // font-weight: @font-weight-semibold;\n`;
    template += `\n`;
    template += `  // Variant overrides\n`;
    template += `  // &.primary {\n`;
    template += `  //   background-color: var(--uls-primary-color);\n`;
    template += `  // }\n`;
    template += `\n`;
    template += `  // State overrides\n`;
    template += `  // &:hover {\n`;
    template += `  //   transform: translateY(-2px);\n`;
    template += `  // }\n`;
    template += `\n`;
    template += `  // &.disabled {\n`;
    template += `  //   opacity: 0.6;\n`;
    template += `  // }\n`;
    template += `}\n`;
  }
  
  return template;
}

function generateFullTemplate(className, name, type) {
  let template = generateBasicTemplate(className, name, type);
  
  if (type !== 'base') {
    template += `\n// ==========================================================================\n`;
    template += `// RESPONSIVE OVERRIDES\n`;
    template += `// ==========================================================================\n\n`;
    template += `@media @mobile-screen {\n`;
    template += `  .${className} {\n`;
    template += `    // Mobile-specific overrides\n`;
    template += `  }\n`;
    template += `}\n`;
  }
  
  return template;
}

function generateMinimalTemplate(className) {
  return `.${className} {\n  // Your overrides here\n}\n`;
}

function getBaseClassName(name) {
  // Convert kebab-case to appropriate base class name
  return name.replace(/-/g, '-');
}

function capitalize(str) {
  return str.split('-').map(word => 
    word.charAt(0).toUpperCase() + word.slice(1)
  ).join(' ');
}

function ensureEntryFile(overridesBaseDir) {
  const entryPath = path.join(overridesBaseDir, ENTRY_FILE_NAME);
  if (!fs.existsSync(entryPath)) {
    const template = generateEntryFileTemplate();
    fs.writeFileSync(entryPath, template, 'utf8');
    console.log(`\n📄 Created override entry file: ${path.relative(process.cwd(), entryPath)}`);
    console.log('   • Keep this file committed so new overrides auto-register');
  }
  return entryPath;
}

function generateEntryFileTemplate() {
  return `// ==========================================================================
// ULS Override Entry Point
// ==========================================================================
// Automatically maintained by the uls-override generator. Each section below
// keeps imports grouped by component type. New overrides will be inserted
// above the AUTO markers - do not remove them.
// ==========================================================================

// Base system overrides (variables, mixins, root config)
@import (optional) "base/root-config.overrides";
${ENTRY_SECTION_MARKERS.base}

// Element overrides (buttons, inputs, etc.)
${ENTRY_SECTION_MARKERS.element}

// Collection overrides (cards, accordions, etc.)
${ENTRY_SECTION_MARKERS.collection}

// Module overrides (dialogs, tables, etc.)
${ENTRY_SECTION_MARKERS.module}

// Theme overrides
${ENTRY_SECTION_MARKERS.theme}

`;
}

function registerOverrideImport(entryPath, componentType, componentName) {
  const relativeImport = `${TYPE_DIRS[componentType] || 'elements'}/${componentName}.overrides`;
  const importLine = `@import (optional) "${relativeImport}";`;
  let contents = fs.readFileSync(entryPath, 'utf8');

  if (contents.includes(importLine)) {
    return;
  }

  const marker = ENTRY_SECTION_MARKERS[componentType] || ENTRY_SECTION_MARKERS.element;
  if (contents.includes(marker)) {
    contents = contents.replace(marker, `${importLine}\n${marker}`);
  } else {
    contents = `${contents.trimEnd()}\n${importLine}\n`;
  }

  fs.writeFileSync(entryPath, contents, 'utf8');
  console.log(`   • Registered @import for ${relativeImport}`);
}

async function promptUsingReadline({ defaults, componentType, outputDir }) {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
  });

  const question = (promptText) => new Promise((resolve) => {
    rl.question(promptText, (answer) => resolve(answer.trim()));
  });

  const ask = async (label, defaultValue, validator) => {
    while (true) {
      const suffix = defaultValue ? ` (${defaultValue})` : '';
      const response = await question(`${label}${suffix}: `);
      const value = response || defaultValue;
      if (!validator || validator(value)) {
        return value;
      }
      console.log('   Please enter a valid value.');
    }
  };

  const askChoice = async (label, choices, defaultValue) => {
    const resolveChoice = (input) => {
      if (!input) {
        return defaultValue;
      }
      const numeric = Number(input);
      if (!Number.isNaN(numeric) && numeric >= 1 && numeric <= choices.length) {
        return choices[numeric - 1].value;
      }
      const normalized = input.toLowerCase();
      const match = choices.find((choice) => choice.value === normalized);
      return match ? match.value : null;
    };

    while (true) {
      console.log('\nComponent types:');
      choices.forEach((choice, index) => {
        console.log(`  ${index + 1}. ${choice.label}`);
      });

      const suffix = defaultValue ? ` (${defaultValue})` : '';
      const answer = await question(`${label}${suffix}: `);
      const result = resolveChoice(answer);
      if (result) {
        return result;
      }
      console.log('   Invalid selection. Enter the number or name from the list above.');
    }
  };

  const componentName = await ask('Component name', '', (val) => !!val && val.length > 0);

  const typeChoices = [
    { value: 'base', label: 'Base (root config, variables)' },
    { value: 'element', label: 'Element (buttons, inputs, etc.)' },
    { value: 'collection', label: 'Collection (cards, accordions, etc.)' },
    { value: 'module', label: 'Module (dialogs, tooltips, etc.)' },
    { value: 'theme', label: 'Theme (theme-specific)' },
  ];

  const resolvedType = await askChoice(
    'Select component type (enter number or name)',
    typeChoices,
    componentType
  );

  const resolvedOutputDir = await ask(
    'Output directory',
    outputDir || defaults.outputDir,
    (val) => !!val && val.length > 0
  );

  rl.close();

  return {
    componentName,
    type: resolvedType,
    outputDir: resolvedOutputDir
  };
}

